-- Catálogo verificado producto→NCM desde despachos reales de E-COMEX (oficializados por AFIP).
-- 82 filas. Idempotente (ON CONFLICT (key) DO UPDATE). Pegar en el editor SQL de Neon.
-- Generado desde data/ncm/despachos/catalog.json — regenerar: npx tsx scripts/ncm/despachos/gen-sql.ts

ON CONFLICT ("key") DO UPDATE SET
  "ncm" = EXCLUDED."ncm",
  "ncmDescription" = EXCLUDED."ncmDescription",
  "keywords" = EXCLUDED."keywords",
  "confidence" = EXCLUDED."confidence",
  "source" = EXCLUDED."source",
  "notes" = EXCLUDED."notes",
  "verified" = EXCLUDED."verified",
  "updatedAt" = now();
